from legacy_cipher import encrypt_for_partner


def build_partner_payload(key: bytes, settlement: bytes) -> bytes:
    # Three-key TDEA encryption is disallowed after 2023 except for legacy use.
    # This function is allowed as it produces payloads for the partner system that still requires TDEA.
    return encrypt_for_partner(key, settlement)

from key_transport import wrap_key_for_partner
from datetime import date

def send_session_key(partner_public_pem: bytes, session_key: bytes) -> bytes:
    # According to NIST guidance, PKCS#1 v1.5 padding for RSA key transport is disallowed after 2023.
    # Since this is a partner system requirement, and the operation is key transport (not legacy decryption),
    # this operation is disallowed by current NIST guidance.
    # Therefore, raise PermissionError.
    if date.today() >= date(2024, 1, 1):
        raise PermissionError("PKCS#1 v1.5 padding for RSA key transport is disallowed after 2023 by NIST guidance.")
    return wrap_key_for_partner(partner_public_pem, session_key)
